WITH base AS (SELECT *, CAST(paid_at AS DATE) paid_at_day FROM payments WHERE paid_at > TO_DATE('2023-07-24') AND order_id IS NOT NULL) SELECT *, SUM(amount) OVER (PARTITION BY status, method) status_sum_amount, MAX(amount) OVER (PARTITION BY order_id, status ORDER BY CAST(paid_at AS BIGINT) RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW) amount_max_90d, FIRST_VALUE(method, TRUE) OVER (ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_method, LAST_VALUE(amount) IGNORE NULLS OVER (PARTITION BY status, method ORDER BY paid_at_day, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_amount, SUM(amount) OVER w_running method_sum_amount FROM base WINDOW w_running AS (PARTITION BY method)
